import functools
import time

def retry(func):
    """
    A decorator that retries a function up to 3 times if an exception is raised.

    Args:
        func (callable): The function to be decorated.

    Returns:
        callable: The wrapped function with retry logic.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        max_attempts = 3
        attempts = 0

        while attempts < max_attempts:
            try:
                return func(*args, **kwargs)
            except Exception as e:
                attempts += 1
                if attempts >= max_attempts:
                    print(f"Final attempt {attempts} failed. Raising exception: {e}")
                    raise e
                print(f"Attempt {attempts} failed: {e}. Retrying...")
                # Small delay between retries to prevent rapid-fire failures
                time.sleep(0.5)

    return wrapper

